// The line view's only door to the database (ADR-0027): the role
// ofm_screens, which can call the functions of migration 018 and nothing
// else. Inputs (msg.topic):
// - "load": the model (config.fn_screen_model) and each line's stops to
//   code (hist.fn_screen_stops_to_code, last 24 hours); at start, every
//   30 s, and after every action
// - "signin" / "setpin" {req}: config.fn_person_sign_in / _set_pin
// - "action" {req}: start, startnew, changeoverdone, complete, code, as the
//   signed-in person (config.fn_person_*)
// Outputs: 1 to the hub: "model", "stops", "result" {req, payload};
// 2 "load" back to this node after a successful action.
const STOP_HOURS = 24;
const pg = global.get("pg");
if (!pg) { node.error("the pg library is not available (see nodered/settings.js)"); return null; }
let pool = context.get("pool");
if (!pool) {
    pool = new pg.Pool({
        host: "timescaledb", port: 5432, database: "ofm", user: "ofm_screens", password: env.get("OFM_SCREENS_DB_PASSWORD"),
        application_name: "ofm-screens", max: 3, connectionTimeoutMillis: 5000, statement_timeout: 20000
    });
    pool.on("error", () => { /* reconnects on the next query */ });
    context.set("pool", pool);
}
const req = msg.req || {};

if (msg.topic === "load") {
    if (context.get("loading")) return null;
    context.set("loading", true);
    try {
        const lines = (await pool.query("SELECT config.fn_screen_model() AS m")).rows[0].m || [];
        const stops = {};
        for (const l of lines) {
            stops[l.id] = (await pool.query(
                "SELECT machine_id, machine_display_name, event_ts::text AS event_ts, extract(epoch FROM event_ts) * 1000 AS event_ms, " +
                "state, fault_code, extract(epoch FROM uncoded_from) * 1000 AS from_ms, uncoded_s, stop_s " +
                "FROM hist.fn_screen_stops_to_code($1, $2)", [l.id, STOP_HOURS])).rows
                .map(r => ({ machineId: r.machine_id, machineName: r.machine_display_name, eventTs: r.event_ts,
                             eventMs: Math.round(Number(r.event_ms)), state: r.state, faultCode: r.fault_code,
                             fromMs: Math.round(Number(r.from_ms)), uncodedS: Math.round(r.uncoded_s), stopS: Math.round(r.stop_s) }));
        }
        node.status({ fill: "green", shape: "dot", text: lines.length + " line(s), " +
                      Object.values(stops).reduce((n, s) => n + s.length, 0) + " stop(s) to code · " + new Date().toLocaleTimeString() });
        return [[{ topic: "model", payload: lines }, { topic: "stops", payload: stops }], null];
    } catch (e) {
        node.status({ fill: "red", shape: "ring", text: "cannot read the model: " + e.message });
        return null;
    } finally {
        context.set("loading", false);
    }
}

if (msg.topic === "signin" || msg.topic === "setpin") {
    try {
        const r = (await pool.query(msg.topic === "signin"
            ? "SELECT result, person_id, display_name, extract(epoch FROM retry_at) * 1000 AS retry_at FROM config.fn_person_sign_in($1, $2, $3)"
            : "SELECT result, person_id, display_name, NULL AS retry_at FROM config.fn_person_set_pin($1, $2, $3)",
            [req.employeeNo, req.pin, req.screen])).rows[0];
        if (r.retry_at !== null) r.retry_at = Math.round(Number(r.retry_at));
        return [{ topic: "result", req: { socketId: req.socketId, screenId: req.screenId, cmd: req.cmd, employeeNo: req.employeeNo }, payload: r }, null];
    } catch (e) {
        return [{ topic: "result", req: { socketId: req.socketId, screenId: req.screenId, cmd: req.cmd }, payload: { result: "error", error: e.message } }, null];
    }
}

if (msg.topic === "action") {
    const calls = {
        start:          ["SELECT config.fn_person_work_order_start($1, $2)", [req.personId, req.workOrderId]],
        startnew:       ["SELECT config.fn_person_work_order_start_new($1, $2, $3, $4)", [req.personId, req.lineId, req.sku, req.qty]],
        changeoverdone: ["SELECT config.fn_person_work_order_changeover_end($1, $2)", [req.personId, req.workOrderId]],
        complete:       ["SELECT config.fn_person_work_order_complete($1, $2)", [req.personId, req.workOrderId]],
        code:           ["SELECT config.fn_person_assign_reason($1, $2, $3::timestamptz, $4, $5)",
                         [req.personId, req.machineId, req.eventTs, req.reasonCode, req.comment]]
    };
    const c = calls[req.cmd];
    if (!c) return null;
    const out = { topic: "result", req: { socketId: req.socketId, screenId: req.screenId, cmd: req.cmd }, payload: {} };
    try {
        await pool.query(c[0], c[1]);
    } catch (e) {
        out.payload.error = e.code === "42501" ? "Sign in again: " + e.message : e.message;
    }
    return [out, out.payload.error ? null : { topic: "load" }];    // after a change, every screen shows it at once
}
return null;

// Connects the line view to the UNS as the read-only MQTT user and keeps
// its subscriptions equal to what the lines need (from the hub): each
// line's .../workorder and .../kpi/+, each machine's .../state and its
// fault code. Output: control messages for the "mqtt in" node.
// The password comes from deploy/.env, so nothing secret is in the flow file.
const want = Array.isArray(msg.payload) ? msg.payload : [];
const had = context.get("topics") || [];
const out = [];
if (!context.get("connected")) {
    out.push({ action: "connect", broker: {
        broker: "mosquitto", port: 1883, clientid: "ofm-screens-" + Math.random().toString(16).slice(2, 8),
        username: "ofm_reader", password: env.get("OFM_MQTT_READER_PASSWORD")
    } });
    context.set("connected", true);
}
const gone = had.filter(t => !want.includes(t));
const added = want.filter(t => !had.includes(t));
if (gone.length) out.push({ action: "unsubscribe", topic: gone });
if (added.length) out.push({ action: "subscribe", topic: added.map(t => ({ topic: t, qos: 1 })) });
context.set("topics", want);
node.status({ fill: "green", shape: "dot", text: want.length + " topics" });
return out.length ? [out] : null;

// Line view hub (ADR-0027, ADR-0028, step 3a.8). Holds what every screen
// shows and who is signed in where; it never touches the database itself.
// Inputs (msg.topic):
// - "model"   the lines from config.fn_screen_model() (node "database")
// - "stops"   {lineId: [stops to code]} (node "database")
// - "result"  the answer to a sign-in or an action (node "database")
// - "tick"    every second: sessions untouched for OFM_SCREEN_IDLE_MINUTES
//             are signed out; every screen gets the current picture
// - a UNS topic: a live value (msg.payload; "" = topic cleared)
// - from the line view (msg._client = the browser): {cmd, ...}
//   hello, touch, signin, setpin, signout, start, startnew, changeoverdone,
//   complete, code
// A person is signed in on one browser page, never on others; a reload or a
// new browser asks again. The page names itself with a random screenId on
// every message, so a sign-in survives the page's connection being
// re-established (Wi-Fi, a tab in the background); answers go to the
// page's current connection (socket).
// Outputs: 1 line view (with msg._client: that browser only); 2 database
// requests; 3 the topics to subscribe to (node "UNS").
const IDLE_MS = Math.max(1, Number(env.get("OFM_SCREEN_IDLE_MINUTES")) || 5) * 60000;
const now = Date.now();
const st = context.get("st") || { lines: [], live: {}, stops: {}, sessions: {} };
context.set("st", st);
const toView = [], toDb = [];
let subscribe = null;

const client = msg._client && msg._client.socketId ? msg._client : null;
const reply = (topic, payload) => toView.push({ topic, payload, _client: client });
const notice = (text, kind) => {                          // cmd: which action it answers
    const cmd = msg.payload && msg.payload.cmd || null;
    if (kind === "error") node.warn("refused " + cmd + ": " + text);      // shows in: docker compose logs screens
    reply("notice", { text, kind: kind || "info", at: now, cmd });
};
const screenId = client ? String(msg.payload && msg.payload.screenId || client.socketId) : null;
const sessionOf = () => {
    const s = screenId && st.sessions[screenId];
    if (s) s.socketId = client.socketId;                  // the page's current connection
    return s;
};
const sessionView = s => s ? { signedIn: true, name: s.name, personId: s.personId, expiresAt: s.last + IDLE_MS }
                           : { signedIn: false };

if (msg.topic === "model") {
    st.lines = Array.isArray(msg.payload) ? msg.payload : [];
    const topics = [];
    for (const l of st.lines) {
        topics.push(l.topic + "/workorder", l.topic + "/kpi/+");
        for (const m of l.machines) {
            topics.push(m.topic + "/state");
            if (m.faultTopic) topics.push(m.faultTopic);
        }
    }
    for (const t of Object.keys(st.live)) {                // forget values of topics no longer shown
        if (!topics.some(p => matches(p, t))) delete st.live[t];
    }
    subscribe = { topic: "subscribe", payload: topics.sort() };
} else if (msg.topic === "stops") {
    st.stops = msg.payload || {};
} else if (msg.topic === "tick") {
    for (const [id, s] of Object.entries(st.sessions)) {
        if (now - s.last > IDLE_MS) {
            delete st.sessions[id];
            toView.push({ topic: "session", payload: { signedIn: false, why: "idle" }, _client: { socketId: s.socketId } });
        }
    }
    toView.push({ topic: "picture", payload: picture() });
} else if (msg.topic === "result") {
    result(msg.req || {}, msg.payload || {});
} else if (client && msg.payload && typeof msg.payload === "object" && msg.payload.cmd) {
    fromScreen(msg.payload);
} else if (typeof msg.topic === "string" && msg.topic.split("/").length >= 5) {
    let v = msg.payload;
    if (typeof v === "string" && v !== "") { try { v = JSON.parse(v); } catch (e) { /* keep as text */ } }
    if (v === "" || v === null || v === undefined) delete st.live[msg.topic];
    else st.live[msg.topic] = v;
}

node.status({ fill: "green", shape: "dot", text: st.lines.length + " line(s), " + Object.keys(st.sessions).length + " signed in" });
return [toView.length ? toView : null, toDb.length ? toDb : null, subscribe];

function fromScreen(p) {
    const s = sessionOf();
    if (p.cmd === "hello") {
        reply("session", sessionView(s));
        reply("picture", picture());
        return;
    }
    if (p.cmd === "touch") {
        if (s) s.last = now;
        reply("session", sessionView(s));
        return;
    }
    if (p.cmd === "signout") {
        delete st.sessions[screenId];
        reply("session", { signedIn: false, why: "signout" });
        return;
    }
    if (p.cmd === "signin" || p.cmd === "setpin") {
        const employeeNo = String(p.employeeNo || "").trim();
        const pin = String(p.pin || "");
        if (!employeeNo) { notice("Type your employee number.", "error"); return; }
        if (p.cmd === "setpin" && !/^[0-9]{4,8}$/.test(pin)) { notice("A PIN is 4 to 8 digits.", "error"); return; }
        toDb.push({ topic: p.cmd, req: { socketId: client.socketId, screenId, cmd: p.cmd, employeeNo, pin, screen: screenName() } });
        return;
    }
    // everything else changes something: only for a signed-in person
    if (!s) {
        reply("session", { signedIn: false, why: "required" });
        notice("Sign in first.", "error");
        return;
    }
    s.last = now;
    const line = st.lines.find(l => l.id === Number(p.lineId));
    if (!line) { notice("Unknown line.", "error"); return; }
    const req = { socketId: client.socketId, screenId, personId: s.personId, cmd: p.cmd, lineId: line.id };
    if (p.cmd === "start") {
        req.workOrderId = Number(p.workOrderId);
        if (!line.plannedOrders.some(o => o.id === req.workOrderId)) { notice("That order is not planned on this line any more.", "error"); return; }
    } else if (p.cmd === "startnew") {
        req.sku = String(p.sku || "");
        req.qty = Math.round(Number(p.qty));
        if (!line.products.some(x => x.sku === req.sku) || !(req.qty > 0)) { notice("Choose a product and a quantity above 0.", "error"); return; }
    } else if (p.cmd === "changeoverdone" || p.cmd === "complete") {
        const wo = st.live[line.topic + "/workorder"];
        if (!wo || !wo.active || wo.workOrderId !== Number(p.workOrderId)) { notice("That order is not running any more.", "error"); return; }
        req.workOrderId = wo.workOrderId;
    } else if (p.cmd === "code") {
        req.machineId = Number(p.machineId);
        req.eventTs = String(p.eventTs || "");                // the event's exact time, as the database wrote it
        req.reasonCode = String(p.reasonCode || "");
        req.comment = p.comment ? String(p.comment).slice(0, 500) : null;
        const reason = line.reasons.find(r => r.code === req.reasonCode);
        if (!reason || (reason.machineId !== null && reason.machineId !== req.machineId) ||
            !(st.stops[line.id] || []).some(x => x.machineId === req.machineId && x.eventTs === req.eventTs)) {
            notice("Choose a reason for one of the stops in the list.", "error");
            return;
        }
    } else {
        node.warn("ignored: " + JSON.stringify(p));
        return;
    }
    toDb.push({ topic: "action", req });
}

function result(req, r) {
    const c = req.socketId ? { socketId: req.socketId } : null;
    const say = (text, kind) => {
        if (kind === "error") node.warn("refused " + req.cmd + ": " + text);
        toView.push({ topic: "notice", payload: { text, kind: kind || "info", at: now, cmd: req.cmd || null }, _client: c });
    };
    if (req.cmd === "signin" || req.cmd === "setpin") {
        if (r.result === "ok" || r.result === "pin_set") {
            const id = req.screenId || req.socketId;
            for (const [other, s] of Object.entries(st.sessions)) {   // one browser page per person
                if (s.personId === r.person_id && other !== id) {
                    delete st.sessions[other];
                    toView.push({ topic: "session", payload: { signedIn: false, why: "elsewhere" }, _client: { socketId: s.socketId } });
                }
            }
            st.sessions[id] = { personId: r.person_id, name: r.display_name, employeeNo: req.employeeNo, last: now, socketId: req.socketId };
            toView.push({ topic: "session", payload: sessionView(st.sessions[id]), _client: c });
            say((r.result === "pin_set" ? "PIN saved. " : "") + "Signed in as " + r.display_name + ".", "ok");
        } else if (r.result === "no_pin") {
            toView.push({ topic: "session", payload: { signedIn: false, choosePin: true, employeeNo: req.employeeNo }, _client: c });
            say("First sign-in: choose a PIN of 4 to 8 digits.");
        } else {
            const text = {
                wrong_pin: "Wrong employee number or PIN.",
                unknown_person: "Wrong employee number or PIN.",
                locked: "Too many wrong PINs: try again at " + (r.retry_at ? new Date(r.retry_at).toTimeString().slice(0, 5) : "later") + ".",
                bad_pin: "A PIN is 4 to 8 digits.",
                pin_exists: "This person already has a PIN: sign in with it.",
                error: "Cannot reach the database: " + (r.error || "")
            }[r.result] || "Sign-in failed (" + r.result + ").";
            say(text, "error");
        }
        return;
    }
    if (r.error) {
        say(r.error, "error");
        return;
    }
    const done = { start: "Order started.", startnew: "Order started.", changeoverdone: "Changeover done.",
                   complete: "Order complete.", code: "Stop coded." }[req.cmd] || "Done.";
    say(done, "ok");
}

// What every screen shows: the lines, each with its live values.
function picture() {
    return {
        serverTime: now,
        lines: st.lines.map(l => ({
            id: l.id, name: l.name, displayName: l.displayName, minorStopS: l.minorStopS, orderRequired: l.orderRequired,
            machines: l.machines.map(m => ({
                id: m.id, name: m.name, displayName: m.displayName, isConstraint: m.isConstraint, isOutput: m.isOutput,
                state: st.live[m.topic + "/state"] || null,
                fault: m.faultTopic ? st.live[m.faultTopic] || null : null
            })),
            workorder: st.live[l.topic + "/workorder"] || null,
            kpi: { hour: st.live[l.topic + "/kpi/hour"] || null, day: st.live[l.topic + "/kpi/day"] || null,
                   order: st.live[l.topic + "/kpi/order"] || null },
            stops: st.stops[l.id] || [],
            reasons: l.reasons, products: l.products, plannedOrders: l.plannedOrders
        }))
    };
}
function screenName() {
    const h = client && client.socketIp ? client.socketIp : null;
    return h ? String(h).slice(0, 64) : null;
}
function matches(pattern, topic) {
    const p = pattern.split("/"), t = topic.split("/");
    if (p.length !== t.length) return false;
    return p.every((x, i) => x === "+" || x === t[i]);
}
